import{_ as t,o as a,c as n,a4 as i}from"./chunks/framework.DMdI2MFY.js";const o="/assets/signal-phone-number.Dd2aa_m8.png",m=JSON.parse('{"title":"VPN update","description":"This page lists frequently asked questions related to the 2026 VPN update.","frontmatter":{"title":"VPN update","category":"FAQ","permalink":"/do-science/faq/vpn-update","outline":1,"description":"This page lists frequently asked questions related to the 2026 VPN update."},"headers":[],"relativePath":"do-science/faq/vpn-update.md","filePath":"do-science/faq/vpn-update.md"}'),r={name:"do-science/faq/vpn-update.md"};function l(s,e,c,d,h,u){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="faq-on-2026-vpn-update" tabindex="-1">FAQ on 2026 VPN update <a class="header-anchor" href="#faq-on-2026-vpn-update" aria-label="Permalink to &quot;FAQ on 2026 VPN update&quot;">​</a></h1><p><strong>This page lists frequently asked questions related to the VPN update in October 2026.</strong></p><nav class="table-of-contents"><ul><li><a href="#general">General</a><ul><li><a href="#why-do-i-need-to-update-my-hunt-cloud-vpn">Why do I need to update my HUNT Cloud VPN?</a></li><li><a href="#when-is-the-update-planned">When is the update planned?</a></li><li><a href="#i-am-away-on-wednesday-can-i-do-the-update-later">I am away on Wednesday. Can I do the update later?</a></li><li><a href="#will-my-current-vpn-be-inactive-immediately-after-the-restart">Will my current VPN be inactive immediately after the restart?</a></li></ul></li><li><a href="#email-notifications">Email notifications</a><ul><li><a href="#the-link-in-my-email-doesn-t-work-now-what">The link in my email doesn&#39;t work. Now what?</a></li></ul></li><li><a href="#receiving-the-new-vpn-configuration">Receiving the new VPN configuration</a><ul><li><a href="#how-will-i-get-my-configurations">How will I get my configurations?</a></li><li><a href="#how-should-i-set-my-signal-privacy-settings">How should I set my Signal privacy settings?</a></li></ul></li><li><a href="#installing-the-new-vpn-configruation">Installing the new VPN configruation</a><ul><li><a href="#i-connect-from-two-machines-do-i-need-to-upgrade-on-both">I connect from two machines. Do I need to upgrade on both?</a></li></ul></li></ul></nav><div class="tip custom-block"><p class="custom-block-title">Need help or got questions?</p><p>The fastest way to get help today (Wednesday) is to contact us in your Slack lab channel. We will also monitor our general <a href="/contact">contact us</a> closely.</p></div><div class="warning custom-block"><p class="custom-block-title">Link to the VPN update guide</p><p><a href="/do-science/guides/access-guides/reset-vpn">Click here</a> to start with your VPN certificate reset.</p></div><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="why-do-i-need-to-update-my-hunt-cloud-vpn" tabindex="-1">Why do I need to update my HUNT Cloud VPN? <a class="header-anchor" href="#why-do-i-need-to-update-my-hunt-cloud-vpn" aria-label="Permalink to &quot;Why do I need to update my HUNT Cloud VPN?&quot;">​</a></h3><p>Our current services have reached a new milestone: 10 years!</p><p>While this is an achievement, it also means that our original VPN root certificate is reaching the end of its 10-year life-time. We therefore need to replace it and issue new VPN user certificates for all lab users.</p><p>Once the new root certificate is activated, all lab users will need to install their new user certificates in order to connect to the VPN and their lab.</p><h3 id="when-is-the-update-planned" tabindex="-1">When is the update planned? <a class="header-anchor" href="#when-is-the-update-planned" aria-label="Permalink to &quot;When is the update planned?&quot;">​</a></h3><p>We plan to send you a new HUNT Cloud VPN configuration on Wednesday 7th October 2026:</p><p><strong>9 AM CET 2026-10-07</strong></p><p>We start to ship new VPN certificates and configuration information to all lab users. You will breifly lose your connection as we test the new root certificate.</p><p><strong>9.30 - 10.00 AM CET</strong></p><p>We will start the VPN service with the new root certificate once most users have received their new certificates. This is expected to take place between 9.30 and 10 AM. All lab users will lose access.</p><p>After the restart, you will need to install the new VPN certificate your received to connect to your lab.</p><h3 id="i-am-away-on-wednesday-can-i-do-the-update-later" tabindex="-1">I am away on Wednesday. Can I do the update later? <a class="header-anchor" href="#i-am-away-on-wednesday-can-i-do-the-update-later" aria-label="Permalink to &quot;I am away on Wednesday. Can I do the update later?&quot;">​</a></h3><p>Yes, you don&#39;t need to do the update when you are back. You can wait until you need access, but you won’t be able to access your lab until you’ve completed the update. Please note that the credentials we sent you are valid for 10 days, so if you wait longer to update, you’ll need to request a new set.</p><h3 id="will-my-current-vpn-be-inactive-immediately-after-the-restart" tabindex="-1">Will my current VPN be inactive immediately after the restart? <a class="header-anchor" href="#will-my-current-vpn-be-inactive-immediately-after-the-restart" aria-label="Permalink to &quot;Will my current VPN be inactive immediately after the restart?&quot;">​</a></h3><p>Yes, there is no delay. The moment we start accepting new VPN configurations all the old ones become inactive.</p><h2 id="email-notifications" tabindex="-1">Email notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email notifications&quot;">​</a></h2><h3 id="the-link-in-my-email-doesn-t-work-now-what" tabindex="-1">The link in my email doesn&#39;t work. Now what? <a class="header-anchor" href="#the-link-in-my-email-doesn-t-work-now-what" aria-label="Permalink to &quot;The link in my email doesn&#39;t work. Now what?&quot;">​</a></h3><p>Worry not. The correct link is:</p><p><a href="/do-science/guides/access-guides/reset-vpn">https://docs.hdc.ntnu.no/do-science/guides/access-guides/reset-vpn</a></p><p>Some of you received an incorrect lab access link in the email with your New VPN certifificate sent Wednesday morning (the link said &quot;None&amp;filter=vpn_reset&quot;). We plan to send the correct link in a new email when we reset the root certificate.</p><h2 id="receiving-the-new-vpn-configuration" tabindex="-1">Receiving the new VPN configuration <a class="header-anchor" href="#receiving-the-new-vpn-configuration" aria-label="Permalink to &quot;Receiving the new VPN configuration&quot;">​</a></h2><h3 id="how-will-i-get-my-configurations" tabindex="-1">How will I get my configurations? <a class="header-anchor" href="#how-will-i-get-my-configurations" aria-label="Permalink to &quot;How will I get my configurations?&quot;">​</a></h3><p>We will send your new VPN certificate over your organizational email, and the passwords for for the 7z file and the VPN password over the Signal mobile app.</p><h3 id="how-should-i-set-my-signal-privacy-settings" tabindex="-1">How should I set my Signal privacy settings? <a class="header-anchor" href="#how-should-i-set-my-signal-privacy-settings" aria-label="Permalink to &quot;How should I set my Signal privacy settings?&quot;">​</a></h3><p>You will receive passwords over the Signal mobile app. You will need to find your phone number in Signal to be able to ship you credentials. You can allow us to find your number by adding the following changes to your Signal Settings:</p><p><img src="'+o+'" alt="signal-phone-number"></p><h2 id="installing-the-new-vpn-configruation" tabindex="-1">Installing the new VPN configruation <a class="header-anchor" href="#installing-the-new-vpn-configruation" aria-label="Permalink to &quot;Installing the new VPN configruation&quot;">​</a></h2><h3 id="i-connect-from-two-machines-do-i-need-to-upgrade-on-both" tabindex="-1">I connect from two machines. Do I need to upgrade on both? <a class="header-anchor" href="#i-connect-from-two-machines-do-i-need-to-upgrade-on-both" aria-label="Permalink to &quot;I connect from two machines. Do I need to upgrade on both?&quot;">​</a></h3><p>Yes, you need to upgrade your VPN certificate on all the machines you use to connect to your lab following the same guide.</p>',35)])])}const f=t(r,[["render",l]]);export{m as __pageData,f as default};
